"""Manually authored clause mappings, keyed by the pinned Nanoka buff IDs.

No runtime prose matching. Values are ratios except flat panel attributes.
Process-only clauses remain in the source text and are excluded from damage.
"""
from dataclasses import dataclass


@dataclass(frozen=True)
class Clause:
    kind: str
    value: float
    elements: tuple[str, ...] = ()
    tags: tuple[str, ...] = ()
    roles: tuple[str, ...] = ()
    state: str | None = None
    personal: bool = False
    maximum: int = 1
    enemy_state: str | None = None
    team_count: tuple[str, int, float, int, float] | None = None
    note: str | None = None
    state_values: tuple[float, ...] | None = None


def c(kind, value, *, el='', tags='', role='', state=None, personal=False, maximum=1, enemy=None, count=None, note=None, values=None):
    return Clause(kind, value, tuple(el.split()), tuple(tags.split()), tuple(role.split()), state, personal, maximum, enemy, count, note, values)


